using TMPro;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using UnityEngine.SceneManagement;

// Test scene for the player's body skins (Horror > Testes > Cena do traje): the game's own player (same
// builder as the house) on a lit floor, wearing the hazmat suit, with a button that swaps the body on the spot
// (BodySkins) and a shooting range for the first person arms. Not in the build. Regenerated by the menu;
// do not edit it by hand.
public static partial class FloodedHouseBuilder
{
    private const string SuitTestScenePath = ProjectPaths.Scenes + "/Tests/SuitTest.unity";

    [MenuItem("Horror/Testes/Cena do traje (troca de corpo)")]
    public static void BuildSuitTestScene()
    {
        GameTuningMenu.Ensure();
        SoundLibraryMenu.Refresh();
        CreateMaterials();
        if (!AssetDatabase.IsValidFolder(ProjectPaths.Scenes + "/Tests"))
        {
            AssetDatabase.CreateFolder(ProjectPaths.Scenes, "Tests");
        }

        ConfigurePipeline();
        Scene scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
        root = new GameObject("SuitTest_Generated").transform;

        // Daylight (Daylight below): sun, sky, ambient from the sky and a daytime eye.
        Group("Lighting");

        Material floorMaterial = Material("SuitTestFloor", Shader.Find("Universal Render Pipeline/Lit"));
        floorMaterial.SetColor("_BaseColor", new Color(0.36f, 0.36f, 0.35f));
        floorMaterial.SetFloat("_Smoothness", 0.25f);
        EditorUtility.SetDirty(floorMaterial);
        Material blockMaterial = Material("SuitTestBlock", Shader.Find("Universal Render Pipeline/Lit"));
        blockMaterial.SetColor("_BaseColor", new Color(0.55f, 0.5f, 0.42f));
        blockMaterial.SetFloat("_Smoothness", 0.2f);
        EditorUtility.SetDirty(blockMaterial);
        Transform set = Group("Set");
        Block("Floor", set, new Vector3(0f, -0.1f, 0f), new Vector3(120f, 0.2f, 120f), floorMaterial);
        // Something to crouch under, step on and stand next to, for scale.
        Block("Step", set, new Vector3(-2.5f, 0.15f, 2f), new Vector3(1.2f, 0.3f, 1.2f), blockMaterial);
        Block("Table", set, new Vector3(2.5f, 0.75f, 2.5f), new Vector3(1.6f, 0.08f, 0.9f), blockMaterial);
        Block("Wall", set, new Vector3(0f, 1.5f, 6f), new Vector3(8f, 3f, 0.2f), blockMaterial);

        Transform post = Group("PostProcessing");
        VolumeProfile look = Profile("SuitTest_Volume");
        BattlefieldGet<Tonemapping>(look).mode.Override(TonemappingMode.ACES);
        Bloom bloom = BattlefieldGet<Bloom>(look);
        bloom.intensity.Override(0.16f);
        bloom.threshold.Override(1.2f);
        EditorUtility.SetDirty(look);
        houseVolume = GlobalVolume("TestVolume", post, look, 0f, 1f);
        underwaterVolume = GlobalVolume("UnderwaterVolume", post, Profile("FloodedHouse_Underwater"), 10f, 0f);

        Transform story = Group("Story");
        Transform spawn = Marker("Spawn", story, new Vector3(0f, 0f, -1.5f), 0f);
        PlayerRig rig = BuildPlayer(story, spawn);
        TMP_FontAsset font = AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(ProjectPaths.Fonts + "/SpecialElite SDF.asset");
        GameObject hudObject = new GameObject("DiveHud");
        hudObject.transform.SetParent(story, false);
        DiveHud hud = hudObject.AddComponent<DiveHud>();
        SetField(hud, "font", font);
        SetField(hud, "air", rig.air);
        SetField(rig.interactor, "hud", hud);
        SetField(rig.gear, "hud", hud);
        SetField(rig.suffocation, "hud", hud);
        SetField(rig.respirator, "hud", hud);
        GameObject menuObject = new GameObject("PauseMenu");
        menuObject.transform.SetParent(story, false);
        PauseMenu menu = menuObject.AddComponent<PauseMenu>();
        SetField(menu, "player", rig.controller);
        SetField(menu, "hud", hud);
        SetField(menu, "font", font);

        // Starts in the suit.
        BodySkins skins = rig.controller.GetComponentInChildren<BodySkins>();
        skins.Apply("Traje");
        EditorUtility.SetDirty(skins);

        // No outside view of the body since 13/10 (Gustavo: first person only for now; OutsideView still exists).
        GameObject panelObject = new GameObject("SkinSwapPanel");
        panelObject.transform.SetParent(story, false);
        SkinSwapPanel panel = panelObject.AddComponent<SkinSwapPanel>();
        SetField(panel, "skins", skins);
        SetField(panel, "player", rig.controller);
        SetField(panel, "gear", rig.gear);
        SetField(panel, "hud", hud);
        SetField(panel, "respirator", rig.respirator);
        SetField(panel, "font", font);

        // 13/10 (Gustavo): a shooting range for the first person animations; no creatures and no reference videos
        // for now. The Drowned (DrownedSetup.PlaceInOpenScene, CombatTestSetup.Arm(..., true)), the tentacle and
        // octopus (TentacleCreatureSetup.PlaceInOpenScene) and the video stages (HandMocapStage, RecordedBody) still
        // have their own menus.
        CombatTestSetup.Arm(rig.controller, false);
        // The backpack, the hand (torch or revolver) and a few pickups on the floor (InventoryTestSetup).
        InventoryTestSetup.Place(rig.controller);
        // Three paper targets on the wall ahead and a firing line (ShootingRangeSetup).
        ShootingRangeSetup.Place();
        // The props generated on 09/10, with name and triangle count, to the right of the start (PropPreviewSetup).
        PropPreviewSetup.Place();

        Daylight();
        EditorSceneManager.SaveScene(scene, SuitTestScenePath);
        AssetDatabase.SaveAssets();
        Debug.Log("[SuitTest] Scene saved to " + SuitTestScenePath);
    }

    // Daytime light for the test scene, as a lit outdoor scene of the game would have it (Gustavo, 07/10: "tudo
    // escuro, nem dá para ver os detalhes da arma"). Measured cause: the old key light shone from in front of the
    // player toward the camera (everything was seen from its unlit side) and the camera's automatic exposure is
    // tuned for the dark house (key 0.03), so in a lit scene it closed by its full 2.5 stops. Now: a warm sun from
    // behind and to the left of the start view, high enough that the body's shadow falls ahead and low; a soft cool
    // sky fill from the opposite side; ambient as a sky / horizon / ground gradient; a procedural sky; and the eye set
    // for daylight (key 0.18, the photographic middle grey). Realtime only: the scene is regenerated and full of
    // moving bodies, so baked light would cost a bake per regeneration and light nothing that moves.
    [MenuItem("Horror/Testes/Luz de dia na cena aberta")]
    public static void Daylight()
    {
        Transform lighting = GameObject.Find("Lighting")?.transform;
        if (lighting == null)
        {
            lighting = new GameObject("Lighting").transform;
        }

        Light sun = Directional(lighting, "Key");
        sun.transform.rotation = Quaternion.Euler(48f, 35f, 0f);
        sun.color = new Color(1f, 0.93f, 0.82f);
        sun.intensity = 2.2f;
        sun.shadows = LightShadows.Soft;
        sun.shadowStrength = 0.85f;
        RenderSettings.sun = sun;
        Light fill = Directional(lighting, "Rim");
        fill.transform.rotation = Quaternion.Euler(30f, 215f, 0f);
        fill.color = new Color(0.62f, 0.74f, 1f);
        fill.intensity = 0.6f;
        fill.shadows = LightShadows.None;

        Material sky = Material("SuitTestSky", Shader.Find("Skybox/Procedural"));
        sky.SetFloat("_SunSize", 0.035f);
        sky.SetFloat("_AtmosphereThickness", 0.9f);
        sky.SetColor("_SkyTint", new Color(0.55f, 0.6f, 0.68f));
        sky.SetColor("_GroundColor", new Color(0.42f, 0.4f, 0.37f));
        sky.SetFloat("_Exposure", 1.2f);
        EditorUtility.SetDirty(sky);
        RenderSettings.skybox = sky;
        RenderSettings.fog = false;
        RenderSettings.ambientMode = AmbientMode.Trilight;
        RenderSettings.ambientSkyColor = new Color(0.52f, 0.6f, 0.74f);
        RenderSettings.ambientEquatorColor = new Color(0.44f, 0.44f, 0.42f);
        RenderSettings.ambientGroundColor = new Color(0.22f, 0.2f, 0.18f);
        RenderSettings.defaultReflectionMode = DefaultReflectionMode.Skybox;
        RenderSettings.reflectionIntensity = 0.8f;
        DynamicGI.UpdateEnvironment();

        foreach (AutoExposure eye in Object.FindObjectsByType<AutoExposure>(FindObjectsInactive.Include))
        {
            eye.Configure(0.18f, 1f, 1.5f, 0.9f, 2f);
            EditorUtility.SetDirty(eye);
        }

        // The front view of the body shows the same sky behind it.
        GameObject outside = GameObject.Find("OutsideCamera");
        if (outside != null)
        {
            outside.GetComponent<Camera>().clearFlags = CameraClearFlags.Skybox;
        }

        EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());
    }

    private static Light Directional(Transform parent, string name)
    {
        Transform existing = parent.Find(name);
        Light light = existing != null ? existing.GetComponent<Light>() : null;
        if (light == null)
        {
            light = new GameObject(name).AddComponent<Light>();
            light.transform.SetParent(parent, false);
        }

        light.type = LightType.Directional;
        return light;
    }

    private static void Block(string name, Transform parent, Vector3 centre, Vector3 size, Material material)
    {
        GameObject block = GameObject.CreatePrimitive(PrimitiveType.Cube);
        block.name = name;
        block.transform.SetParent(parent, false);
        block.transform.localPosition = centre;
        block.transform.localScale = size;
        block.GetComponent<MeshRenderer>().sharedMaterial = material;
    }
}
